log.command:
mkdir -p compositions && cat > compositions/title-open.html <<'EOF'
<!doctype html>
<html>
  <head>
    <meta charset="UTF-8" />
  </head>
  <body>
    <template>
      <style>
        #title-open-root {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #fffaf0;
          font-family: ui-sans-serif, system-ui, sans-serif;
          text-shadow: 0 4px 40px rgba(30, 20, 50, 0.55);
        }
        #title-open-kicker {
          font-size: 34px;
          font-weight: 600;
          letter-spacing: 0.42em;
          text-transform: uppercase;
        }
      </style>

      <div id="title-open-root" data-composition-id="title-open" data-width="1920" data-height="1080">
        <div id="title-open-kicker">A lotus lake, in watercolour</div>
      </div>

      <script>
        const tl = gsap.timeline({ paused: true });
        tl.fromTo("#title-open-kicker", { opacity: 0, scale: 1.18, filter: "blur(10px)" },
          { opacity: 0.95, scale: 1, filter: "blur(0px)", duration: 1.1, ease: "expo.out" }, 0.2);
        tl.to("#title-open-kicker", { opacity: 0, y: -20, filter: "blur(8px)", duration: 0.45, ease: "power2.in" }, 1.5);
        window.__timelines["title-open"] = tl;
      </script>
    </template>
  </body>
</html>
EOF
